// Mimics Python's int(str) for decimal integer literals:
// strip ASCII whitespace, optional single sign, digits with single
// underscores allowed only strictly between two digits.

const PYTHON_INT_RE = /^[+-]?[0-9](?:_?[0-9])*$/;

export function tryParsePythonInt(str) {
  const trimmed = str.replace(/^[ \t\n\r\f\v]+|[ \t\n\r\f\v]+$/g, '');
  if (!PYTHON_INT_RE.test(trimmed)) {
    return null;
  }
  return BigInt(trimmed.replace(/_/g, ''));
}

