// Python repr() emulation for the value types this project handles.
// Pure Node.js ESM, no external dependencies.

// Python repr() of a string: single-quoted, with backslash, single quote,
// newline, tab, and carriage return escaped.
function pyStrRepr(str) {
  let out = "'";
  for (const ch of str) {
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === "'") {
      out += "\\'";
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === '\r') {
      out += '\\r';
    } else {
      out += ch;
    }
  }
  out += "'";
  return out;
}

// Python repr() of a dict: {} when empty, else {'k1': v1, 'k2': v2}
// in Map insertion order. Values are rendered recursively via pyRepr.
export function pyDictRepr(map) {
  if (map.size === 0) {
    return '{}';
  }
  const parts = [];
  for (const [key, value] of map) {
    parts.push(pyStrRepr(key) + ': ' + pyRepr(value));
  }
  return '{' + parts.join(', ') + '}';
}

// Python repr() of a supported value:
//   BigInt -> decimal string (matches Python int repr, incl. negatives)
//   string -> single-quoted Python string repr
//   Map (string keys) -> Python dict repr
export function pyRepr(value) {
  if (typeof value === 'bigint') {
    return String(value);
  }
  if (typeof value === 'string') {
    return pyStrRepr(value);
  }
  if (value instanceof Map) {
    return pyDictRepr(value);
  }
  throw new TypeError('pyRepr: unsupported value type');
}

