import { pyRepr } from './pyrepr.mjs';

export class DeepDiff {
  constructor(t1, t2) {
    this.t1 = t1;
    this.t2 = t2;
    this.result = this._compute(t1, t2);
  }

  _compute(t1, t2) {
    // Equal dicts -> no diff
    if (t1.size === t2.size) {
      let equal = true;
      for (const [k, v] of t1) {
        if (!t2.has(k) || t2.get(k) !== v) {
          equal = false;
          break;
        }
      }
      if (equal) return '{}';
    }

    // Cutoff: collapse whole comparison to root values_changed
    const m = Math.min(t1.size, t2.size);
    const M = Math.max(t1.size, t2.size);
    if (M >= 2 && M > 3 * m) {
      return (
        "{'values_changed': {'root': {'new_value': " +
        pyRepr(t2) +
        ", 'old_value': " +
        pyRepr(t1) +
        '}}}'
      );
    }

    // Per-item diff
    const added = []; // keys in t2 not t1, t2 order
    for (const k of t2.keys()) {
      if (!t1.has(k)) added.push(k);
    }
    const removed = []; // keys in t1 not t2, t1 order
    for (const k of t1.keys()) {
      if (!t2.has(k)) removed.push(k);
    }
    const changed = []; // keys in both with differing values, t1 order
    for (const [k, v] of t1) {
      if (t2.has(k) && t2.get(k) !== v) changed.push(k);
    }

    const sections = [];
    if (added.length > 0) {
      const items = added.map((k) => `"root[${pyRepr(k)}]"`).join(', ');
      sections.push(`'dictionary_item_added': [${items}]`);
    }
    if (removed.length > 0) {
      const items = removed.map((k) => `"root[${pyRepr(k)}]"`).join(', ');
      sections.push(`'dictionary_item_removed': [${items}]`);
    }
    if (changed.length > 0) {
      const items = changed
        .map(
          (k) =>
            `"root[${pyRepr(k)}]": {'new_value': ${pyRepr(
              t2.get(k)
            )}, 'old_value': ${pyRepr(t1.get(k))}}`
        )
        .join(', ');
      sections.push(`'values_changed': {${items}}`);
    }

    if (sections.length === 0) return '{}';
    return `{${sections.join(', ')}}`;
  }

  toString() {
    return this.result;
  }
}

