// Minimal emulation of Python's argparse for this project.
// Supports only what the entry script needs: required `--x X` options of
// type 'int', `-h`/`--help`, `--x=value` form, and argparse-compatible
// usage/error output.

import { tryParsePythonInt } from './pyint.mjs';

export class ArgumentParser {
  constructor({ prog }) {
    this.prog = prog;
    // Argument specs in add order: { flag, dest, metavar, type, required }
    this._arguments = [];
  }

  addArgument(flag, { type, required } = {}) {
    const dest = flag.replace(/^--/, '');
    this._arguments.push({
      flag,
      dest,
      metavar: dest.toUpperCase(),
      type: type || null,
      required: Boolean(required),
    });
  }

  _usageLine() {
    const parts = ['usage:', this.prog, '[-h]'];
    for (const arg of this._arguments) {
      parts.push(`${arg.flag} ${arg.metavar}`);
    }
    return parts.join(' ');
  }

  _printHelp() {
    const lines = [this._usageLine(), '', 'options:'];
    lines.push('  -h, --help  show this help message and exit');
    for (const arg of this._arguments) {
      lines.push(`  ${arg.flag} ${arg.metavar}`);
    }
    process.stdout.write(lines.join('\n') + '\n');
    process.exit(0);
  }

  _error(message) {
    process.stderr.write(this._usageLine() + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  // A token starting with '-' counts as a value only if it parses as a
  // (negative) Python int, e.g. '-5' or '-1_0'.
  _looksLikeNegativeNumber(token) {
    return token.startsWith('-') && tryParsePythonInt(token) !== null;
  }

  _convertValue(arg, raw) {
    if (arg.type === 'int') {
      const value = tryParsePythonInt(raw);
      if (value === null) {
        this._error(`argument ${arg.flag}: invalid int value: '${raw}'`);
      }
      return value;
    }
    return raw;
  }

  parseArgs(argv) {
    const byFlag = new Map(this._arguments.map((a) => [a.flag, a]));
    const values = new Map();
    const extras = [];

    let i = 0;
    while (i < argv.length) {
      const token = argv[i];

      if (token === '-h' || token === '--help') {
        this._printHelp();
      }

      let flag = token;
      let inlineValue = null;
      if (token.startsWith('--')) {
        const eq = token.indexOf('=');
        if (eq !== -1) {
          flag = token.slice(0, eq);
          inlineValue = token.slice(eq + 1);
        }
      }

      const arg = byFlag.get(flag);
      if (!arg) {
        // Unknown flag or stray positional: collect for later error.
        extras.push(token);
        i += 1;
        continue;
      }

      let raw;
      if (inlineValue !== null) {
        raw = inlineValue;
        i += 1;
      } else {
        const next = argv[i + 1];
        const nextIsValue =
          next !== undefined &&
          (!next.startsWith('-') || this._looksLikeNegativeNumber(next));
        if (!nextIsValue) {
          this._error(`argument ${arg.flag}: expected one argument`);
        }
        raw = next;
        i += 2;
      }

      values.set(arg.dest, this._convertValue(arg, raw)); // last occurrence wins
    }

    const missing = this._arguments
      .filter((a) => a.required && !values.has(a.dest))
      .map((a) => a.flag);
    if (missing.length > 0) {
      this._error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length > 0) {
      this._error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    const result = {};
    for (const arg of this._arguments) {
      if (values.has(arg.dest)) {
        result[arg.dest] = values.get(arg.dest);
      }
    }
    return result;
  }
}

