import { ArgumentParser } from '/output/lib/argparse.mjs';
const mk = () => { const p = new ArgumentParser({ prog: 'test12.mjs' }); for (const f of ['--a','--b','--c','--d']) p.addArgument(f, { type: 'int', required: true }); return p; };
// 1. valid parse incl. = form, negative, underscores, last-wins
const r = mk().parseArgs(['--a','5','--b=-1_0','--c','+7','--a','9','--d','0']);
console.log('parse:', JSON.stringify(r, (k,v) => typeof v === 'bigint' ? v.toString()+'n' : v));
"

